-- One-off seed: a 把 vs 被 custom mini lesson for Jerome, requested in chat
-- before the in-app lesson-authoring tools were reachable from that session.
-- Scoped to the account email; inserts nothing if the user does not exist.
-- Easily removed later via DELETE /api/custom-lessons/:id or the MCP tool.

INSERT INTO custom_lessons (id, user_id, title, description, icon, spec, source, status)
SELECT
  'seed-ba-bei-lesson-0001',
  u.id,
  '把 vs 被',
  'Telling apart 把 (you do something TO the object) and 被 (the subject has something done to it)',
  '🔀',
  '{"title":"把 vs 被","icon":"🔀","description":"Telling apart 把 (you do something TO the object) and 被 (the subject has something done to it)","sections":[{"title":"The idea","exercises":[{"type":"note","title":"Two sides of the same event","body":"把 (bǎ) and 被 (bèi) describe the same event from opposite directions.\n\n把 = the DOER is the subject. You grab the object and do something to it: Subject 把 Object Verb+result. Memory hook: 把 has the hand radical 扌— a hand grabbing the object.\n\n被 = the RECEIVER is the subject. Something happens TO it: Subject 被 (doer) Verb+result. Memory hook: 被 has the clothes radical 衤— think of being covered by a blanket, something done to you.\n\nBoth need a verb with a result (了, 完, 走, 在…). You cannot end with a bare verb.","sentences":[{"hanzi":"我把咖啡喝完了。","pinyin":"wǒ bǎ kā fēi hē wán le.","english":"I finished the coffee. (I did it — 把)"},{"hanzi":"咖啡被我喝完了。","pinyin":"kā fēi bèi wǒ hē wán le.","english":"The coffee got finished by me. (it happened to the coffee — 被)"}]},{"type":"match","pairs":[{"hanzi":"拿走","pinyin":"ná zǒu","english":"take away"},{"hanzi":"打破","pinyin":"dǎ pò","english":"break"},{"hanzi":"放在","pinyin":"fàng zài","english":"put (somewhere)"},{"hanzi":"吃掉","pinyin":"chī diào","english":"eat up"}]}]},{"title":"Spot the difference","exercises":[{"type":"choice","question":"Your little brother took your phone. Which is correct?","options":[{"hanzi":"我的手机被弟弟拿走了。","pinyin":"wǒ de shǒu jī bèi dì di ná zǒu le.","english":"My phone was taken by my little brother."},{"hanzi":"我的手机把弟弟拿走了。","pinyin":"wǒ de shǒu jī bǎ dì di ná zǒu le.","english":"My phone took my little brother away(!)"}],"correct":0,"explanation":"The subject is the phone, and the phone RECEIVES the action, so it needs 被. With 把 the phone would be doing the taking — it would carry your brother off."},{"type":"choice","question":"You want to say: I put the book on the table.","options":[{"hanzi":"我把书放在桌子上了。","pinyin":"wǒ bǎ shū fàng zài zhuō zi shàng le.","english":"I put the book on the table."},{"hanzi":"我被书放在桌子上了。","pinyin":"wǒ bèi shū fàng zài zhuō zi shàng le.","english":"I was put on the table by the book(!)"},{"hanzi":"书把我放在桌子上了。","pinyin":"shū bǎ wǒ fàng zài zhuō zi shàng le.","english":"The book put me on the table(!)"}],"correct":0,"explanation":"You are the doer and the book is what gets moved, so: 我 把 书 + verb + place. 把 pulls the object in front of the verb so the sentence can say WHERE it ends up."}]},{"title":"Build it","exercises":[{"type":"scramble","english":"The window was broken by him.","tiles":["窗户","被","他","打破","了"],"correct_order":["窗户","被","他","打破","了"]},{"type":"scramble","english":"I put my phone in the bag.","tiles":["我","把","手机","放在","包里","了"],"correct_order":["我","把","手机","放在","包里","了"]},{"type":"translate","english":"The cake was eaten up by my little sister.","reference_hanzi":"蛋糕被妹妹吃掉了。","reference_pinyin":"dàn gāo bèi mèi mei chī diào le.","note":"Did you start from the cake and use 被 + doer + verb + result?"},{"type":"translate","english":"Please close the door.","reference_hanzi":"请把门关上。","reference_pinyin":"qǐng bǎ mén guān shàng.","note":"Requests about handling an object love 把: 请把 + object + verb + result."},{"type":"speak","prompt":"Say one 把 sentence and one 被 sentence about things in your kitchen — out loud.","example":{"hanzi":"我把牛奶放进冰箱了。","pinyin":"wǒ bǎ niú nǎi fàng jìn bīng xiāng le.","english":"I put the milk in the fridge."}}]}]}',
  'api',
  'active'
FROM users u
WHERE u.email = 'jeromeswannack@gmail.com';
